// === TOPIC GENERATOR ===
// Pilih topik secara acak atau ambil dari input webhook
const topics = [
  "5 Fakta AI yang Mengubah Dunia",
  "Cara Cepat Belajar Coding Tanpa Kelas",
  "Rahasia Produktivitas Orang Sukses",
  "Tips Trading Crypto untuk Pemula",
  "Teknologi yang Akan Menggantikan Pekerjaan Manusia",
  "5 Aplikasi AI Gratis yang Wajib Kamu Coba",
  "Cara Passive Income dari Internet",
  "Hack Otak untuk Belajar 2x Lebih Cepat"
];

// Ambil dari webhook body jika ada, atau random
const webhookBody = $input.first()?.json?.body || {};
const topic = webhookBody.topic || topics[Math.floor(Math.random() * topics.length)];
const niche = webhookBody.niche || 'teknologi & produktivitas';
const voice = webhookBody.voice || 'id-ID-ArdiNeural';
const platforms = webhookBody.platforms || ['telegram', 'facebook'];

return [{
  json: {
    topic,
    niche,
    voice,
    platforms
  }
}];

// === SCRIPTWRITER ===
// Generate naskah dengan struktur hook + scenes + CTA
const { topic, niche, voice, platforms } = $input.first().json;

// Template skrip berdasarkan topik
const scriptTemplates = {
  default: [
    {
      text: `STOP SCROLLING! Ini fakta tentang ${topic} yang WAJIB kamu tahu!`,
      image_prompt: `dramatic cinematic opener, dark background, glowing text effect, 9:16 portrait, ultra HD`
    },
    {
      text: `Fakta pertama yang bikin kamu terkejut adalah ini. Dan kebanyakan orang belum tahu tentang ${topic}.`,
      image_prompt: `shocked person looking at phone, vibrant colors, modern office, 9:16 portrait cinematic`
    },
    {
      text: `Nomor dua yang paling penting. ${topic} bisa mengubah cara kamu bekerja selamanya.`,
      image_prompt: `futuristic technology concept, blue neon lights, abstract digital waves, 9:16 portrait`
    },
    {
      text: `Fakta ketiga yang bahkan para ahli pun akui. Ini bukan hype. Ini nyata.`,
      image_prompt: `professional expert presenting data charts, modern minimal design, 9:16 portrait`
    },
    {
      text: `Jika kamu suka konten seperti ini, follow sekarang dan klik notifikasi biar gak ketinggalan!`,
      image_prompt: `subscribe button animation, like and follow icons, vibrant gradient background, 9:16 portrait`
    }
  ]
};

const scenes = scriptTemplates.default;
const fullScript = scenes.map(s => s.text).join(' ');
const title = `${topic} | Tips ${niche} #shorts`;
const description = `${fullScript}\n\n#shorts #${niche.replace(/ /g,'').replace('&','')} #viral #tips`;

return [{
  json: {
    topic,
    niche,
    voice,
    platforms,
    scenes,
    title,
    description
  }
}];

const renderResult = $input.first().json;
const prevData = $('✍️ Scriptwriter AI').first().json;

if (renderResult.status !== 'success') {
  throw new Error('Render gagal: ' + (renderResult.message || 'unknown error'));
}

return [{
  json: {
    video_path: renderResult.video_path,
    title: prevData.title,
    description: prevData.description,
    platforms: prevData.platforms,
    topic: prevData.topic
  }
}];

const publishResult = $input.first().json;
const prevData = $('✅ Cek Hasil Render').first().json;

const successPlatforms = Object.entries(publishResult.results || {})
  .filter(([k, v]) => v === 'ok')
  .map(([k]) => k);

const failedPlatforms = Object.entries(publishResult.results || {})
  .filter(([k, v]) => v !== 'ok')
  .map(([k, v]) => `${k}: ${v}`);

const report = [
  `✅ *Video Berhasil Dipublish!*`,
  `📌 Topik: ${prevData.topic}`,
  `🎬 File: ${prevData.video_path}`,
  `✅ Sukses: ${successPlatforms.join(', ') || 'tidak ada'}`,
  failedPlatforms.length ? `❌ Gagal: ${failedPlatforms.join(', ')}` : '',
].filter(Boolean).join('\n');

console.log(report);
return [{ json: { report, ...publishResult } }];
